import { useNavigate } from 'react-router-dom';
import { useApp } from '../../context/AppContext';
import Pricing from './Pricing';
import './PricingPage.css';

export default function PricingPage() {
  const navigate = useNavigate();
  const { t, user } = useApp();

  return (
    <div className="pricing-page">
      <div className="pricing-page__card">
        <button type="button" className="pricing-page__back" onClick={() => navigate('/')}>
          {t('pricing.backButton')}
        </button>
        <h1 className="pricing-page__title">{t('pricing.pageTitle')}</h1>
        <Pricing />
        {!user.isAuthenticated && <p className="pricing-page__hint">{t('pricing.pageSignupHint')}</p>}
      </div>
    </div>
  );
}
